  
      const SONG =
        "";
    
      /* ✏️ Personalize here: who it is for, who it is from, and (optional) the WhatsApp number with country code, digits only */
      const C = { to: "Jaan", from: "Your Admirer", phone: "" };
      const $ = (s) => document.querySelector(s),
        $$ = (s) => [...document.querySelectorAll(s)];
      $$(".to").forEach((e) => (e.textContent = C.to));
      $$(".from").forEach((e) => (e.textContent = C.from));
      document.documentElement.classList.add("lock");

      const M = [
        [
          "Your Smile",
          "Teri ek smile se meri poori duniya roshan ho jaati hai.",
        ],
        [
          "Your Heart",
          "You are the kindest soul I know, and I’m lucky to see it.",
        ],
        [
          "Your Voice",
          "Tumhari awaaz sunna mere din ka sabse sukoon bhara pal hai.",
        ],
        ["Your Laugh", "The sound of your laughter is my favourite song."],
        ["Your Eyes", "Tumhari aankhon mein mujhe apna ghar dikhta hai."],
        ["Your Presence", "Wherever you are is where I feel most like myself."],
      ];
      const R = [
        "Teri hasi meri bad mood ki dawai hai.",
        "You listen — truly listen.",
        "Tumhare saath chup rehna bhi comfortable lagta hai.",
        "The way you laugh at your own jokes.",
        "You make ordinary days feel special.",
        "Chai ho ya long drive, tum ho toh sab perfect.",
        "Your kindness, even when no one is watching.",
        "You feel like home.",
        "You make me want to be a better person.",
        "Tum ho, isliye sab kuch achha lagta hai.",
      ];

      function type(el, txt, sp, cb) {
        el.textContent = "";
        let i = 0;
        clearInterval(el._t);
        el._t = setInterval(() => {
          if (i >= txt.length) {
            clearInterval(el._t);
            return cb && cb();
          }
          el.textContent += txt[i++];
        }, sp || 36);
      }

      function openGate() {
        play();
        $("#gate").classList.add("out");
        document.documentElement.classList.remove("lock");
        burst(innerWidth / 2, innerHeight / 2, 60);
        setTimeout(
          () =>
            type(
              $("#tag"),
              "I’ve been wanting to tell you something…",
              40,
              () =>
                setTimeout(
                  () =>
                    type(
                      $("#tag"),
                      "Something I could never say out loud.",
                      40,
                    ),
                  900,
                ),
            ),
          700,
        );
      }
      $("#gate").onclick = openGate;
      $("#gate").onkeydown = (e) => {
        if (e.key === "Enter" || e.key === " ") openGate();
      };

      $("#msgs").innerHTML = M.map(
        ([t, m], i) =>
          '<div class="flip reveal" style="--d:' +
          i * 0.08 +
          's" tabindex="0"><div><div class="f"><svg width="34" height="34"><use href="#h"/></svg><h3>' +
          t +
          '</h3><small>Tap to open</small></div><div class="b">' +
          m +
          "</div></div></div>",
      ).join("");
      $("#msgs").onclick = (e) => {
        const f = e.target.closest(".flip");
        if (f) f.classList.toggle("on");
      };
      $("#msgs").onkeydown = (e) => {
        if (e.key === "Enter" || e.key === " ") {
          const f = e.target.closest(".flip");
          if (f) {
            e.preventDefault();
            f.classList.toggle("on");
          }
        }
      };

      let ri = 0;
      function reason() {
        type($("#reason"), R[ri % R.length], 28);
        $("#rc").textContent =
          "Reason " + ((ri % R.length) + 1) + " of " + R.length;
        ri++;
      }
      $("#rb").onclick = () => {
        reason();
        burst(innerWidth / 2, innerHeight * 0.5, 10);
      };
      reason();

      const io = new IntersectionObserver(
        (es) =>
          es.forEach((e) => {
            if (e.isIntersecting) {
              e.target.classList.add("in");
              io.unobserve(e.target);
            }
          }),
        { threshold: 0.15 },
      );
      $$(".reveal").forEach((e) => io.observe(e));
      addEventListener(
        "scroll",
        () => {
          const h = document.documentElement;
          $("#bar").style.width =
            (scrollY / Math.max(1, h.scrollHeight - innerHeight)) * 100 + "%";
        },
        { passive: true },
      );

      let th = matchMedia("(prefers-color-scheme:dark)").matches
        ? "dark"
        : "light";
      $("#th").textContent = th === "dark" ? "☀" : "☾";
      $("#th").onclick = () => {
        th = th === "dark" ? "light" : "dark";
        document.documentElement.dataset.theme = th;
        $("#th").textContent = th === "dark" ? "☀" : "☾";
      };

      /* the question */
      let n = 0;
      const NO = [
        "No",
        "Are you sure? 🥺",
        "Think again 💭",
        "Pretty please?",
        "Last chance 😢",
        "Okay… just press Yes 😄",
      ];
      function dodge(e) {
        if (e && e.cancelable) e.preventDefault();
        n++;
        const w = Math.min(innerWidth - 160, 340);
        $("#nb").style.transform =
          "translate(" +
          (Math.random() - 0.5) * w +
          "px," +
          (Math.random() - 0.5) * 130 +
          "px)";
        $("#nb").textContent = NO[Math.min(n, NO.length - 1)];
        $("#yb").style.transform = "scale(" + Math.min(1 + n * 0.18, 2.2) + ")";
      }
      $("#nb").addEventListener("pointerenter", dodge);
      $("#nb").addEventListener("touchstart", dodge, { passive: false });
      $("#nb").addEventListener("click", dodge);
      $("#yb").onclick = () => {
        $("#wa").href =
          "https://wa.me/" +
          C.phone +
          "?text=" +
          encodeURIComponent("Yes! 💖 I’m yours too.\n\n" + location.href);
        $("#yes").classList.add("on");
        [0.2, 0.5, 0.8, 0.35, 0.65].forEach((x, i) =>
          setTimeout(
            () => burst(innerWidth * x, innerHeight * 0.55, 80),
            i * 260,
          ),
        );
      };
      $("#cl").onclick = () => $("#yes").classList.remove("on");

      /* song: starts at 0:20 of the original track, loops from there */
      let au = null,
        on = false;
      try {
        const s = atob(SONG),
          u = new Uint8Array(s.length);
        for (let i = 0; i < s.length; i++) u[i] = s.charCodeAt(i);
        au = new Audio(
          URL.createObjectURL(new Blob([u], { type: "audio/mpeg" })),
        );
        au.loop = true;
        au.volume = 0.85;
        au.preload = "auto";
      } catch (e) {}
      function mu() {
        $("#mu").classList.toggle("off", !on);
        $("#mu").textContent = on ? "🔊" : "🔇";
      }
      function play() {
        if (au)
          au.play()
            .then(() => {
              on = true;
              mu();
            })
            .catch(() => {
              on = false;
              mu();
            });
      }
      $("#mu").onclick = () => {
        if (!au) return;
        if (on) {
          au.pause();
          on = false;
          mu();
        } else play();
      };
      document.addEventListener("visibilitychange", () => {
        if (!au || !on) return;
        document.hidden ? au.pause() : au.play().catch(() => {});
      });

      /* hearts + confetti */
      const cv = $("#fx"),
        c = cv.getContext("2d"),
        col = ["#ff7eb3", "#f0467f", "#f9b8d4", "#ffc27a", "#d7a8ff"];
      const rm = matchMedia("(prefers-reduced-motion:reduce)").matches;
      let W,
        H,
        P = [];
      const rs = () => {
        W = cv.width = innerWidth;
        H = cv.height = innerHeight;
      };
      rs();
      addEventListener("resize", rs);
      function heart(x, y, s) {
        c.beginPath();
        c.moveTo(x, y + s * 0.3);
        c.bezierCurveTo(x, y, x - s * 0.5, y, x - s * 0.5, y + s * 0.3);
        c.bezierCurveTo(x - s * 0.5, y + s * 0.6, x, y + s * 0.8, x, y + s);
        c.bezierCurveTo(
          x,
          y + s * 0.8,
          x + s * 0.5,
          y + s * 0.6,
          x + s * 0.5,
          y + s * 0.3,
        );
        c.bezierCurveTo(x + s * 0.5, y, x, y, x, y + s * 0.3);
        c.fill();
      }
      function burst(x, y, k) {
        for (let i = 0; i < k; i++) {
          const t = Math.random() * 6.28,
            f = 3 + Math.random() * 7;
          P.push({
            x,
            y,
            s: 6 + Math.random() * 12,
            vx: Math.cos(t) * f,
            vy: Math.sin(t) * f - 4,
            c: col[i % 5],
            k: 1,
            l: 90 + Math.random() * 60,
          });
        }
      }
      addEventListener("pointerdown", (e) => {
        if (!e.target.closest("button,a,.flip,.gate"))
          burst(e.clientX, e.clientY, 12);
      });
      function loop() {
        c.clearRect(0, 0, W, H);
        if (!rm && P.length < 30 && Math.random() < 0.08)
          P.push({
            x: Math.random() * W,
            y: H + 20,
            s: 8 + Math.random() * 16,
            v: 0.4 + Math.random(),
            w: Math.random() * 6,
            c: col[(Math.random() * 5) | 0],
            a: 0.25 + Math.random() * 0.4,
          });
        P = P.filter((p) => (p.k ? p.l-- > 0 : p.y > -40));
        for (const p of P) {
          if (p.k) {
            p.vy += 0.18;
            p.x += p.vx;
            p.y += p.vy;
            p.vx *= 0.99;
            c.globalAlpha = Math.min(1, p.l / 40);
          } else {
            p.y -= p.v;
            p.w += 0.02;
            p.x += Math.sin(p.w) * 0.6;
            c.globalAlpha = p.a;
          }
          c.fillStyle = p.c;
          heart(p.x, p.y, p.s);
        }
        c.globalAlpha = 1;
        requestAnimationFrame(loop);
      }
      loop();
   